def rounded_avg(n, m):
    if n > m:
        return -1

    count = m - n + 1
    total = (n + m) * count // 2

    q, r = divmod(total, count)
    comparison = 2 * r - count

    if comparison > 0:
        q += 1
    elif comparison == 0 and q % 2 == 1:
        q += 1

    return bin(q)
