from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        max_group = max(groups)
        assigned = [-1] * (max_group + 1)
        seen = set()

        for idx, val in enumerate(elements):
            if val > max_group or val in seen:
                continue

            seen.add(val)
            for multiple in range(val, max_group + 1, val):
                if assigned[multiple] == -1:
                    assigned[multiple] = idx

        return [assigned[g] for g in groups]
