class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def all_substrings(x: str):
            res = [""]
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    res.append(x[i:j])
            return res

        subs = all_substrings(s)
        subt = all_substrings(t)

        ans = 0
        for a in subs:
            for b in subt:
                if len(a) + len(b) <= ans:
                    continue
                c = a + b
                if c == c[::-1]:
                    ans = len(c)

        return ans
