from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1

        seg = [-1] * (2 * size)
        for i, cap in enumerate(baskets):
            seg[size + i] = cap

        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i * 2], seg[i * 2 + 1])

        def find_first(x: int) -> int:
            if seg[1] < x:
                return -1

            node = 1
            while node < size:
                left = node * 2
                if seg[left] >= x:
                    node = left
                else:
                    node = left + 1
            return node - size

        unplaced = 0

        for f in fruits:
            pos = find_first(f)

            if pos == -1:
                unplaced += 1
            else:
                node = size + pos
                seg[node] = -1
                node //= 2

                while node:
                    seg[node] = max(seg[node * 2], seg[node * 2 + 1])
                    node //= 2

        return unplaced
