def magic_square_test(matrix):
    if not matrix:
        return False

    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    values = [x for row in matrix for x in row]
    if len(values) != len(set(values)):
        return False

    target = sum(matrix[0])

    if any(sum(row) != target for row in matrix):
        return False

    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != target:
            return False

    if sum(matrix[i][i] for i in range(n)) != target:
        return False

    if sum(matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True


