from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        online = [True] * numberOfUsers
        offline_until = [0] * numberOfUsers

        # OFFLINE events must be processed before MESSAGE events at the same timestamp.
        events.sort(key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for typ, ts_str, data in events:
            ts = int(ts_str)

            # Process automatic comebacks before handling this event.
            for u in range(numberOfUsers):
                if not online[u] and offline_until[u] <= ts:
                    online[u] = True

            if typ == "MESSAGE":
                for token in data.split():
                    if token == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif token == "HERE":
                        for u in range(numberOfUsers):
                            if online[u]:
                                mentions[u] += 1
                    else:
                        mentions[int(token[2:])] += 1
            else:  # OFFLINE
                uid = int(data[2:] if data.startswith("id") else data)
                online[uid] = False
                offline_until[uid] = ts + 60

        return mentions
