class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        best_gain = 0

        for target in range(1, 51):
            cur = 0
            max_gain = 0

            for v in nums:
                if v == target:
                    cur += 1
                if v == k:
                    cur -= 1

                if cur < 0:
                    cur = 0
                elif cur > max_gain:
                    max_gain = cur

            if max_gain > best_gain:
                best_gain = max_gain

        return total_k + best_gain
